where not exists (select 1 from category.locations where location_type_id = 1 and upper(code) = 'NE');
update category.locations set value_translations = '{"en-US":"Niger","fa-IR":"نیجر","ar-SA":"النيجر","tr-TR":"Nijer"}'::jsonb || value_translations, last_modified_date = now()
where location_type_id = 1 and upper(code) = 'NE' and not (value_translations ?& array['en-US','fa-IR','ar-SA','tr-TR']);

