from category.locations c
join category.locations p on p.location_type_id = 3 and p.parent_id = c.id and upper(p.code) = 'AR-03'
where city.location_type_id = 2 and upper(city.code) = 'RESISTENCI' and city.parent_id = c.id
  and c.location_type_id = 1 and upper(c.code) = 'AR';

