join category.locations p on p.location_type_id = 3 and p.parent_id = c.id and upper(p.code) = 'ES-29'
where c.location_type_id = 1 and upper(c.code) = 'ES'
  and not exists (
    select 1
    from category.locations existing
    left join category.locations existing_parent on existing_parent.id = existing.parent_id
    where existing.location_type_id = 2
      and upper(existing.code) = 'VALDEFUENT'
      and (existing.parent_id = c.id or existing_parent.parent_id = c.id)
  );
update category.locations city
set parent_id = p.id, last_modified_date = now()
from category.locations c
join category.locations p on p.location_type_id = 3 and p.parent_id = c.id and upper(p.code) = 'ES-29'
where city.location_type_id = 2 and upper(city.code) = 'VALDEFUENT' and city.parent_id = c.id
  and c.location_type_id = 1 and upper(c.code) = 'ES';

