join category.locations p on p.location_type_id = 3 and p.parent_id = c.id and upper(p.code) = 'PL-73'
where city.location_type_id = 2 and upper(city.code) = 'GRUDZIADZ' and city.parent_id = c.id
  and c.location_type_id = 1 and upper(c.code) = 'PL';

