from category.locations c
join category.locations p on p.location_type_id = 3 and p.parent_id = c.id and upper(p.code) = 'SE-26'
where city.location_type_id = 2 and upper(city.code) = 'VASASTADEN' and city.parent_id = c.id
  and c.location_type_id = 1 and upper(c.code) = 'SE';

insert into category.locations (id, code, value_translations, location_type_id, parent_id, create_date, display_order)
select gen_random_uuid(), 'TABY', '{"en-US":"Täby"}'::jsonb, 2, p.id, now(), 58123
from category.locations c
join category.locations p on p.location_type_id = 3 and p.parent_id = c.id and upper(p.code) = 'SE-26'
where c.location_type_id = 1 and upper(c.code) = 'SE'
  and not exists (
    select 1
    from category.locations existing
    left join category.locations existing_parent on existing_parent.id = existing.parent_id
    where existing.location_type_id = 2
      and upper(existing.code) = 'TABY'
      and (existing.parent_id = c.id or existing_parent.parent_id = c.id)
  );
